import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def as_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        try:
            return (datetime(1899, 12, 30) + timedelta(days=float(value))).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y",
            "%m/%d/%y",
            "%d-%b-%Y",
            "%d-%b-%y",
        ):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    return None

today = as_date(vws["C3"].value)

# Date columns and fallback department codes:
# D = C74 start, E = C75 start, G = C76 start, I = C77 start, K = C78 start
date_cols = [
    ("D", "C74"),
    ("E", "C75"),
    ("G", "C76"),
    ("I", "C77"),
    ("K", "C78"),
]

results = []

# Employees are in rows 4 through 19; answer region is B2:B17.
for r in range(4, 20):
    current = None
    for col, fallback_code in date_cols:
        d = as_date(vws[f"{col}{r}"].value)
        if d is not None and today is not None and today >= d:
            code = vws[f"{col}1"].value
            if code is None:
                code = fallback_code
            if not isinstance(code, str):
                code = str(code)
            current = code.strip()
    results.append(current)

for i, value in enumerate(results):
    ws.cell(row=2 + i, column=2, value=value)

wb.save(OUT)

print("today:", today)
print("count:", len(results))
print("first:", results[:3])
print("last:", results[-3:])
